from lib import Buku
INFAK='muafakatcare.my/infak'
def e1():
    b=Buku('30-hadis-tentang-memberi','30 Hadis Tentang Memberi','Satu hadis sehari untuk hati yang suka bersedekah')
    b.teks('Cara guna eBook ini','Tiga puluh hadis pendek tentang sedekah, memberi makan, menjaga yang lemah dan adab memberi. Baca satu sehari, sebaiknya selepas Subuh.',
      ['Baca teks Arab dan terjemahannya perlahan-lahan.','Lihat baris <b>Amalkan hari ini</b> dan pilih satu perbuatan kecil.','Kongsi halaman yang menyentuh hati anda dengan keluarga.'],
      'Hadis disusun dalam lima bahagian: kelebihan sedekah (1–8), sedekah yang kecil (9–14), memberi makan dan menjaga yang lemah (15–21), pahala yang berterusan (22–25) dan adab memberi (26–30).',eyebrow='Pengenalan')
    H=[('muslim',6592,'Sedekah tidak mengurangkan harta','Sedekah tidak mengurangkan harta. Tidaklah seseorang memaafkan orang lain melainkan Allah menambah kemuliaannya, dan tidaklah seseorang merendah diri kerana Allah melainkan Allah mengangkat darjatnya.','Sedekahkan jumlah yang selalu anda rasa “sayang” untuk dilepaskan.'),
    ('bukhari',1442,'Doa dua malaikat setiap pagi','Tiada satu hari pun yang hamba-hamba memasuki waktu pagi melainkan dua malaikat turun. Salah satunya berdoa: “Ya Allah, berilah ganti kepada orang yang berinfak.” Yang satu lagi berdoa: “Ya Allah, berilah kebinasaan kepada orang yang menahan hartanya.”','Mulakan pagi ini dengan satu infak, walaupun kecil.'),
    ('bukhari',5352,'Berinfaklah, Allah akan berinfak kepadamu','Allah berfirman: “Berinfaklah wahai anak Adam, nescaya Aku akan berinfak kepadamu.”','Beri dahulu sebelum anda rasa “cukup”.'),
    ('bukhari',1433,'Jangan menahan','Janganlah engkau menahan hartamu, nanti Allah menahan (kurnia-Nya) daripadamu.','Semak satu barang di rumah yang tidak digunakan dan berikan kepada yang memerlukan.'),
    ('bukhari',1417,'Walau separuh biji kurma','Jagalah diri kamu daripada api neraka walaupun dengan (bersedekah) separuh biji kurma.','Jangan tunggu jumlah besar. RM1 hari ini lebih baik daripada RM100 yang ditangguh.'),
    ('bukhari',6806,'Tujuh golongan di bawah naungan Allah','Tujuh golongan dinaungi Allah pada hari yang tiada naungan kecuali naungan-Nya: pemimpin yang adil; pemuda yang membesar dalam ibadah kepada Allah; lelaki yang mengingati Allah ketika bersendirian lalu mengalir air matanya; lelaki yang hatinya terpaut pada masjid; dua orang yang saling mencintai kerana Allah; lelaki yang diajak oleh wanita yang berkedudukan dan cantik lalu dia berkata, “Aku takut kepada Allah”; dan lelaki yang bersedekah secara sembunyi sehingga tangan kirinya tidak tahu apa yang diberikan oleh tangan kanannya.','Buat satu sedekah hari ini yang tiada siapa tahu.'),
    ('bukhari',1429,'Tangan yang di atas','Tangan yang di atas lebih baik daripada tangan yang di bawah. Tangan yang di atas ialah yang memberi, dan tangan yang di bawah ialah yang meminta.','Jadilah pihak yang menawarkan bantuan dahulu, sebelum diminta.'),
    ('bukhari',1419,'Sedekah yang paling besar pahalanya','Seorang lelaki bertanya: “Wahai Rasulullah, sedekah apakah yang paling besar pahalanya?” Baginda menjawab: “Engkau bersedekah ketika engkau sihat, sayang akan harta, takut miskin dan mengharapkan kekayaan. Jangan engkau tangguhkan sehingga nyawa sampai di kerongkong, lalu engkau berkata: ‘Untuk si fulan sekian, untuk si fulan sekian,’ sedangkan harta itu sudah pun menjadi hak si fulan.”','Tetapkan satu infak tetap bulanan sekarang, ketika anda masih sihat.'),
    ('tirmidhi',1970,'Wajah yang manis','Setiap kebaikan ialah sedekah. Antara kebaikan itu ialah engkau menemui saudaramu dengan wajah yang manis, dan engkau menuangkan air dari timbamu ke dalam bekas saudaramu.','Senyum kepada tiga orang hari ini, termasuk ahli keluarga sendiri.'),
    ('bukhari',2891,'Sedekah setiap sendi','Setiap sendi manusia wajib bersedekah setiap hari. Membantu seseorang menaiki tunggangannya atau mengangkatkan barangnya ke atasnya ialah sedekah. Perkataan yang baik ialah sedekah. Setiap langkah menuju solat ialah sedekah, dan menunjukkan jalan ialah sedekah.','Bantu seseorang mengangkat barang atau tunjukkan jalan dengan sabar.'),
    ('muslim',2328,'Setiap kebaikan ialah sedekah','Setiap kebaikan ialah sedekah.','Kira lima kebaikan kecil yang anda buat hari ini. Semuanya dikira.'),
    ('bukhari',2320,'Menanam pokok','Tidaklah seorang Muslim menanam pokok atau menyemai benih, lalu hasilnya dimakan oleh burung, manusia atau haiwan, melainkan ia menjadi sedekah baginya.','Tanam sesuatu, atau siram pokok yang memberi manfaat kepada orang lain.'),
    ('muslim',6688,'Banyakkan kuahnya','Wahai Abu Zar, apabila engkau memasak kuah, banyakkanlah airnya dan berilah kepada jiranmu.','Lebihkan sedikit masakan hari ini untuk seorang jiran.'),
    ('bukhari',6236,'Memberi makan dan memberi salam','Seorang lelaki bertanya kepada Nabi: “Amalan Islam apakah yang terbaik?” Baginda menjawab: “Engkau memberi makan, dan engkau memberi salam kepada orang yang engkau kenal dan yang tidak engkau kenal.”','Beri salam kepada orang yang anda tidak kenal hari ini.'),
    ('bukhari',3046,'Tiga perintah ringkas','Bebaskanlah tawanan, berilah makan orang yang lapar dan ziarahilah orang yang sakit.','Hubungi seorang kenalan yang sedang sakit.'),
    ('bukhari',5353,'Membantu janda dan orang miskin','Orang yang berusaha membantu janda dan orang miskin adalah seperti orang yang berjihad di jalan Allah, atau seperti orang yang solat sepanjang malam dan berpuasa sepanjang siang.','Kenal pasti seorang ibu tunggal di sekitar anda dan tanya apa yang dia perlukan.'),
    ('bukhari',5304,'Bersama Nabi di syurga','“Aku dan orang yang menanggung anak yatim berada di syurga seperti ini,” lalu Baginda mengisyaratkan jari telunjuk dan jari tengah serta merenggangkan sedikit antara keduanya.','Sumbang kepada keperluan sekolah seorang anak yatim.'),
    ('muslim',6552,'Menziarahi orang sakit','Sesiapa yang menziarahi orang sakit, dia sentiasa berada di taman buah-buahan syurga sehingga dia pulang.','Rancang satu ziarah minggu ini, walaupun sepuluh minit.'),
    ('tirmidhi',1924,'Sayangilah yang di bumi','Orang-orang yang penyayang akan disayangi oleh Ar-Rahman. Sayangilah mereka yang di bumi, nescaya Yang di langit akan menyayangi kamu. Rahim (hubungan kekeluargaan) itu berasal daripada nama Ar-Rahman; sesiapa yang menyambungnya, Allah menyambungnya, dan sesiapa yang memutuskannya, Allah memutuskannya.','Hubungi seorang saudara yang sudah lama tidak anda tanya khabar.'),
    ('muslim',2322,'Nafkah keluarga ialah sedekah','Apabila seorang Muslim membelanjakan nafkah untuk keluarganya dengan mengharapkan pahala, ia menjadi sedekah baginya.','Niatkan belanja dapur hari ini sebagai ibadah.'),
    ('tirmidhi',807,'Memberi makan orang berpuasa','Sesiapa yang memberi makan berbuka kepada orang yang berpuasa, dia mendapat pahala seperti orang itu, tanpa mengurangkan pahala orang yang berpuasa itu sedikit pun.','Taja juadah berbuka untuk seseorang pada Isnin atau Khamis ini.'),
    ('muslim',4223,'Tiga amalan yang tidak terputus','Apabila seseorang meninggal dunia, terputuslah amalannya kecuali tiga perkara: sedekah jariah, ilmu yang dimanfaatkan, atau anak soleh yang mendoakannya.','Fikirkan satu wakaf yang boleh anda mulakan, walaupun secara berkongsi.'),
    ('bukhari',1409,'Dua orang yang boleh dicemburui','Tidak boleh iri hati kecuali terhadap dua orang: orang yang Allah kurniakan harta lalu dia membelanjakannya pada jalan yang benar, dan orang yang Allah kurniakan hikmah lalu dia memutuskan perkara dengannya dan mengajarkannya.','Contohi seorang dermawan yang anda kenal. Tanya bagaimana dia bermula.'),
    ('bukhari',6462,'Sedikit tetapi berterusan','Aisyah berkata: “Amalan yang paling disukai oleh Rasulullah ialah amalan yang dilakukan oleh pelakunya secara berterusan.”','Pilih jumlah yang anda mampu ulang setiap hari, bukan jumlah yang besar sekali sahaja.'),
    ('bukhari',3554,'Lebih pemurah daripada angin','Ibnu Abbas berkata: “Nabi ialah orang yang paling pemurah, dan Baginda lebih pemurah lagi pada bulan Ramadan ketika Jibril menemuinya. Jibril menemuinya pada setiap malam Ramadan untuk bertadarus Al-Quran dengannya. Sungguh, Rasulullah lebih pemurah dalam kebaikan daripada angin yang bertiup.”','Rancang infak Ramadan anda dari sekarang.'),
    ('bukhari',1,'Semuanya bermula dengan niat','Sesungguhnya setiap amalan bergantung pada niat, dan setiap orang mendapat apa yang diniatkannya. Sesiapa yang berhijrah kerana dunia yang ingin diperolehnya atau kerana wanita yang ingin dikahwininya, maka hijrahnya adalah kepada apa yang dia tuju.','Sebelum menekan butang infak, perbaharui niat: kerana Allah.'),
    ('bukhari',1410,'Daripada hasil yang baik','Sesiapa yang bersedekah senilai sebiji kurma daripada hasil usaha yang baik, dan Allah tidak menerima kecuali yang baik, maka Allah menerimanya dengan tangan kanan-Nya, kemudian mengembangkannya untuk pemiliknya sebagaimana seseorang daripada kamu membesarkan anak kudanya, sehingga ia menjadi sebesar gunung.','Pastikan sumber sedekah anda halal dan bersih.'),
    ('bukhari',3467,'Rahmat kepada semua makhluk','Ketika seekor anjing berpusing-pusing di sekeliling sebuah perigi dan hampir mati kehausan, seorang wanita pelacur daripada Bani Israil melihatnya. Dia menanggalkan kasutnya lalu memberinya minum. Maka Allah mengampuninya kerana perbuatan itu.','Letakkan sebekas air untuk kucing atau burung di luar rumah.'),
    ('nasai',3665,'Sedekah air',"Sa'ad bin Ubadah berkata: “Aku bertanya: Wahai Rasulullah, sedekah apakah yang paling utama?” Baginda menjawab: “Memberi minum air.”",'Sediakan air minuman untuk pekerja, penghantar barang atau jemaah masjid.'),
    ('bukhari',2260,'Amanah dalam menyampaikan','Penjaga amanah yang jujur, yang menyerahkan apa yang diperintahkan kepadanya dengan rela hati, ialah salah seorang daripada dua orang yang bersedekah.','Jika anda memegang amanah orang, sampaikan sepenuhnya dan segera.')]
    for i,(bk,no,tj,tr,am) in enumerate(H,1): b.hadis(i,bk,no,tr,am,tj)
    b.teks('Senarai semak saya','Tandakan hadis yang sudah anda amalkan bulan ini.','<ul class="semak">'+''.join(f'<li>{x}</li>' for x in ['Sedekah pada waktu pagi','Sedekah secara sembunyi','Memberi makan seseorang','Menziarahi atau menghubungi orang sakit','Membantu ibu tunggal atau anak yatim','Menyambung silaturahim','Memulakan satu infak tetap','Memperbaharui niat sebelum memberi'])+'</ul>',eyebrow='Muhasabah')
    b.tutup('Teruskan memberi','Sedekah yang paling disukai ialah yang berterusan walaupun sedikit. Pilih satu saluran dan jadikan ia amalan tetap.',INFAK,'Infak bersama Muafakat Care')
    return b
def e3():
    b=Buku('20-ayat-infak-dalam-al-quran','20 Ayat Infak dalam Al-Quran','Tadabbur ringkas untuk si pemberi')
    b.teks('Tadabbur dalam lima minit','Tadabbur bermaksud berhenti dan memikirkan apa yang Allah katakan kepada kita. Untuk setiap ayat:',['Baca ayat dan terjemahannya dua kali.','Baca catatan ringkas di bawahnya.','Jawab soalan <b>Tanya diri</b> dengan jujur.'],'Terjemahan dalam eBook ini dipetik daripada Tafsir Pimpinan Ar-Rahman. Catatan tadabbur ialah renungan ringkas, bukan tafsir lengkap; rujuklah kitab tafsir atau guru untuk kefahaman yang lebih mendalam.',eyebrow='Pengenalan')
    A=[('2:261','Sebiji benih, tujuh ratus biji',['Allah membandingkan infak dengan benih yang ditanam. Benih itu hilang dari tangan kita, tetapi ia tidak hilang; ia sedang tumbuh.','Gandaan itu milik Allah. Tugas kita hanya menanam.'],'Benih apa yang saya tanam minggu ini?'),
    ('2:262','Memberi tanpa mengungkit',['Pahala dijanjikan kepada mereka yang tidak mengiringi pemberian dengan ungkitan atau kata-kata yang menyakitkan.','Selepas memberi, lepaskan. Jangan simpan sebagai hutang budi.'],'Pernahkah saya mengungkit pemberian saya?'),
    ('2:263','Kata-kata yang baik',['Jika tidak mampu memberi, perkataan yang baik dan kemaafan sudah menjadi kebaikan.','Menolak dengan lembut lebih mulia daripada memberi sambil menyakiti.'],'Bagaimana cara saya menolak permintaan orang?'),
    ('2:267','Beri daripada yang baik',['Allah menyuruh kita menginfakkan hasil yang baik, bukan memilih yang buruk untuk diberikan.','Ukurannya mudah: adakah saya sendiri sudi menerimanya?'],'Adakah barang yang saya sedekahkan itu saya sendiri mahu terima?'),
    ('2:271','Terang atau sembunyi',['Kedua-duanya baik. Sedekah terang boleh menjadi contoh; sedekah sembunyi lebih menjaga hati dan maruah penerima.'],'Sedekah saya yang mana lebih banyak: yang dilihat orang atau yang tidak?'),
    ('2:274','Siang dan malam',['Ayat ini memuji mereka yang berinfak pada setiap masa dan keadaan. Infak bukan acara bermusim.','Mereka dijanjikan tiada ketakutan dan tiada kesedihan.'],'Bilakah waktu yang saya boleh jadikan waktu tetap untuk memberi?'),
    ('2:245','Pinjaman yang baik',['Allah yang Maha Kaya menggunakan perkataan “pinjaman” untuk pemberian kita, lalu menjanjikan gandaan yang banyak.','Dia yang menyempitkan dan melapangkan rezeki.'],'Adakah saya percaya “pinjaman” ini pasti dibayar?'),
    ('2:215','Kepada siapa dahulu?',['Ayat ini menyusun keutamaan: ibu bapa, kerabat, anak yatim, orang miskin dan musafir.','Kebajikan bermula dari yang paling dekat.'],'Siapa orang paling dekat dengan saya yang memerlukan bantuan?'),
    ('3:92','Apa yang kamu sayangi',['Kebajikan yang sempurna dicapai apabila kita sanggup memberi sebahagian daripada apa yang kita sayangi.','Memberi lebihan itu baik; memberi yang disayangi itu lebih tinggi.'],'Apa yang saya sayang, tetapi sanggup saya beri?'),
    ('3:134','Ketika senang dan susah',['Sifat orang bertakwa: berinfak pada masa lapang dan sempit, menahan marah dan memaafkan.','Infak ketika sempit mungkin kecil jumlahnya, tetapi besar nilainya.'],'Adakah saya berhenti memberi apabila kewangan terasa sempit?'),
    ('76:8-9','Memberi makan kerana Allah',['Mereka memberi makan kepada orang miskin, anak yatim dan tawanan, sedangkan mereka sendiri menyukai makanan itu.','Mereka tidak mengharapkan balasan atau ucapan terima kasih.'],'Adakah saya kecewa apabila pemberian saya tidak dihargai?'),
    ('34:39','Dia akan menggantikannya',['Apa sahaja yang diinfakkan, Allah menggantikannya. Dia sebaik-baik pemberi rezeki.','Ganti itu tidak semestinya wang; ia boleh jadi kesihatan, ketenangan atau terhindar daripada musibah.'],'Apakah “ganti” yang pernah saya rasai?'),
    ('57:11','Siapakah yang mahu?',['Ayat ini berbentuk pertanyaan, seolah-olah satu jemputan terbuka kepada sesiapa yang mahu.'],'Apa jawapan saya kepada jemputan ini hari ini?'),
    ('57:7','Harta itu amanah',['Kita hanyalah wakil yang diberi kuasa menguruskan harta itu buat sementara.','Menginfakkan sebahagiannya ialah menunaikan amanah, bukan kehilangan.'],'Jika harta ini pinjaman, bagaimana saya menguruskannya?'),
    ('63:10','Sebelum terlambat',['Ayat ini menggambarkan penyesalan orang yang meminta ditangguhkan ajalnya sebentar supaya dapat bersedekah.'],'Apa sedekah yang saya asyik tangguhkan?'),
    ('64:16','Sekadar kemampuan',['Bertakwalah sekadar kemampuan, dan berinfaklah untuk kebaikan diri sendiri.','Sesiapa yang dipelihara daripada sifat kedekut dirinya, dialah orang yang berjaya.'],'Apa yang menghalang saya: tidak mampu, atau tidak sanggup?'),
    ('65:7','Ikut kemampuan masing-masing',['Yang lapang memberi mengikut kelapangannya; yang sempit memberi daripada apa yang Allah kurniakan kepadanya.','Allah tidak membebankan seseorang melebihi apa yang diberikan-Nya.'],'Berapa jumlah yang benar-benar padan dengan kemampuan saya?'),
    ('92:5-7','Jalan yang dimudahkan',['Sesiapa yang memberi, bertakwa dan membenarkan balasan yang terbaik, Allah mudahkan baginya jalan kesenangan.'],'Urusan mana yang saya harap Allah mudahkan?'),
    ('51:19','Ada hak orang lain',['Dalam harta orang bertakwa ada hak bagi yang meminta dan yang tidak meminta.','Ramai yang memerlukan tetapi malu untuk meminta.'],'Siapa di sekeliling saya yang memerlukan tetapi tidak meminta?'),
    ('14:31','Sebelum datang hari itu',['Dirikan solat dan berinfaklah, secara sembunyi dan terang, sebelum datang hari yang tiada lagi jual beli dan persahabatan.'],'Jika hari ini peluang terakhir, apa yang saya mahu beri?')]
    for i,a in enumerate(A,1): b.ayat(i,*a)
    b.tutup('Daripada tadabbur kepada amalan','Pilih satu ayat yang paling menyentuh hati anda, dan jadikan ia sebab untuk satu amalan tetap.',INFAK,'Infak bersama Muafakat Care')
    return b
